import{_ as t,c as s,o as r,af as i,j as e}from"./chunks/framework.DanHQscr.js";const g=JSON.parse('{"title":"Depth-First and Breadth-First Search","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/13-2D-search.md","filePath":"lectures/13-2D-search.md","lastUpdated":1759856123000}'),l={name:"lectures/13-2D-search.md"};function n(o,a,h,d,c,p){return r(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="depth-first-and-breadth-first-search" tabindex="-1">Depth-First and Breadth-First Search <a class="header-anchor" href="#depth-first-and-breadth-first-search" aria-label="Permalink to “Depth-First and Breadth-First Search”">​</a></h1><p>Maze Solving</p><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to “Learning Outcomes”">​</a></h2><p>After completing this lecture and the related lab, students will be able to:</p><ol><li><p>Explain the conceptual differences between Depth-First Search (DFS) and Breadth-First Search (BFS) algorithms.</p></li><li><p>Describe how recursion, stacks, and queues support systematic exploration of a 2D maze.</p></li><li><p>Implement DFS and BFS algorithms in C++ to determine whether a maze can be solved.</p></li><li><p>Compare the performance and pathfinding results of DFS and BFS in terms of completeness, optimality, and memory use.</p></li><li><p>Debug and trace recursive and iterative search algorithms to observe traversal order and backtracking.</p></li><li><p>Extend maze-solving algorithms to handle advanced cases such as weighted moves or warp locations.</p></li><li><p>Relate maze traversal techniques to broader search problems, including graph traversal and web crawling.</p></li></ol><h2 id="lecture-video" tabindex="-1">Lecture Video <a class="header-anchor" href="#lecture-video" aria-label="Permalink to “Lecture Video”">​</a></h2>',6),e("div",{class:"youtube"},[e("div",null,[e("iframe",{width:"853",height:"480",src:"https://www.youtube-nocookie.com/embed/ekTfwviCYhA?rel=0&showinfo=0",title:"CSCI 315",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:"allowfullscreen"})])],-1),i(`<h2 id="🧩-overview" tabindex="-1">🧩 Overview <a class="header-anchor" href="#🧩-overview" aria-label="Permalink to “🧩 Overview”">​</a></h2><ul><li>Goal: Write programs to <strong>solve 2D mazes</strong> using <strong>Depth-First Search (DFS)</strong> and <strong>Breadth-First Search (BFS)</strong>.</li><li>Reinforces key Data Structures concepts: <ul><li>Recursion</li><li>Stacks and Queues</li><li>Searching algorithms</li><li>Structs, pointers, and heap memory</li></ul></li><li>Application links to <strong>Project 2</strong> and upcoming <strong>Binary Search Trees</strong>.</li></ul><h2 id="🧱-representing-the-maze" tabindex="-1">🧱 Representing the Maze <a class="header-anchor" href="#🧱-representing-the-maze" aria-label="Permalink to “🧱 Representing the Maze”">​</a></h2><ul><li>Maze stored as a <strong>1D array</strong> (for heap allocation) visualized in 2D.</li><li>Defined Constant (<code>enum</code>) values: <ul><li><code>O</code> = Open path</li><li><code>W</code> = Wall</li><li><code>V</code> = Visited</li></ul></li><li>Each position tracked using a <code>Point</code> struct:<div class="language-cpp line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Point</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> row;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> col; </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> distance;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // optional for BFS </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div></li><li>Helper functions: <ul><li>Convert between 2D coordinates and 1D index.</li><li>Overloaded <code>==</code> operator for comparing points.</li><li><code>printMaze()</code> visualizes traversal.</li></ul></li></ul><h2 id="🔍-depth-first-search-dfs" tabindex="-1">🔍 Depth-First Search (DFS) <a class="header-anchor" href="#🔍-depth-first-search-dfs" aria-label="Permalink to “🔍 Depth-First Search (DFS)”">​</a></h2><h3 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to “Concept”">​</a></h3><ul><li>Explore one path <strong>deeply before backtracking</strong>.</li><li>Implemented <strong>recursively</strong> or using a <strong>stack</strong>.</li><li>Great for finding <em>a</em> solution, but <strong>not necessarily the shortest</strong>.</li></ul><h3 id="algorithm" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm" aria-label="Permalink to “Algorithm”">​</a></h3><ol><li>Base cases: <ul><li>Out of bounds → stop</li><li>Hit a wall (<code>W</code>) → stop</li><li>Already visited (<code>V</code>) → stop</li><li>Reached end → success</li></ul></li><li>Mark current cell as visited.</li><li>Recursively explore neighbors (e.g., up, right, down, left).</li><li>If no direction leads to the goal → backtrack.</li></ol><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h3><ul><li>Recursive DFS uses the <strong>call stack</strong>.</li><li>Iterative DFS uses an explicit <code>std::stack&lt;Point&gt;</code>.</li><li>Order of exploration affects path pattern.</li><li>Pros: <ul><li>Simple to implement.</li></ul></li><li>Cons: <ul><li>Can be inefficient (explores long wrong paths).</li><li>Not guaranteed to find the shortest path.</li></ul></li></ul><h2 id="🌐-breadth-first-search-bfs" tabindex="-1">🌐 Breadth-First Search (BFS) <a class="header-anchor" href="#🌐-breadth-first-search-bfs" aria-label="Permalink to “🌐 Breadth-First Search (BFS)”">​</a></h2><h3 id="concept-1" tabindex="-1">Concept <a class="header-anchor" href="#concept-1" aria-label="Permalink to “Concept”">​</a></h3><ul><li>Explores <strong>all possible moves one step at a time</strong>.</li><li>Implemented using a <strong>queue</strong> (<code>std::queue&lt;Point&gt;</code>).</li><li>Guaranteed to find the <strong>shortest path</strong>.</li></ul><h3 id="algorithm-1" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm-1" aria-label="Permalink to “Algorithm”">​</a></h3><ol><li>Enqueue the start point.</li><li>While queue not empty: <ul><li>Dequeue a point (<code>current</code>).</li><li>If it’s the end → done.</li><li>For each valid move (up, down, left, right):</li><li>If unvisited and open, mark visited and enqueue new point.</li></ul></li><li>Track <code>distance</code> for shortest path calculation.</li></ol><h3 id="notes-1" tabindex="-1">Notes <a class="header-anchor" href="#notes-1" aria-label="Permalink to “Notes”">​</a></h3><ul><li>BFS processes nodes <strong>in order of distance</strong> (first-in, first-out).</li><li>Useful for <strong>shortest-path problems</strong>.</li><li>Higher memory use, but predictable runtime growth.</li></ul><h2 id="⚖️-dfs-vs-bfs-comparison" tabindex="-1">⚖️ DFS vs BFS Comparison <a class="header-anchor" href="#⚖️-dfs-vs-bfs-comparison" aria-label="Permalink to “⚖️ DFS vs BFS Comparison”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th>DFS</th><th>BFS</th></tr></thead><tbody><tr><td style="text-align:right;">Data Structure</td><td>Stack (or recursion)</td><td>Queue</td></tr><tr><td style="text-align:right;">Search Style</td><td>Deep</td><td>Broad</td></tr><tr><td style="text-align:right;">Finds Shortest Path?</td><td>❌ No</td><td>✅ Yes</td></tr><tr><td style="text-align:right;">Overall Memory Usage</td><td>Lower</td><td>Higher</td></tr><tr><td style="text-align:right;">Implementation</td><td>Often recursive</td><td>Iterative</td></tr><tr><td style="text-align:right;">Backtracking</td><td>Implicit</td><td>Not needed</td></tr></tbody></table><p>Depth-First Search (DFS) generally uses less memory than Breadth-First Search (BFS) because BFS must keep many nodes in memory at once, while DFS only keeps one active path.</p><h2 id="🚀-extensions" tabindex="-1">🚀 Extensions <a class="header-anchor" href="#🚀-extensions" aria-label="Permalink to “🚀 Extensions”">​</a></h2><h3 id="heuristic-search-a" tabindex="-1">Heuristic Search (A*) <a class="header-anchor" href="#heuristic-search-a" aria-label="Permalink to “Heuristic Search (A*)”">​</a></h3><ul><li>Improves DFS by prioritizing moves that appear closer to the goal.</li><li>Trades <strong>accuracy</strong> for <strong>speed</strong> using “good-enough” paths.</li></ul><h3 id="project-extensions" tabindex="-1">Project Extensions <a class="header-anchor" href="#project-extensions" aria-label="Permalink to “Project Extensions”">​</a></h3><ul><li><strong>Priority Queue / Insert with Priority</strong><ul><li>Used to simulate priority-based traversal.</li></ul></li><li><strong>Mazes with Warps</strong><ul><li>Special numeric cells act as teleporters.</li><li>Warp target computed via:<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">row </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">col </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li>Warps cost 1 step like normal moves.</li></ul></li></ul><h2 id="🧠-key-takeaways" tabindex="-1">🧠 Key Takeaways <a class="header-anchor" href="#🧠-key-takeaways" aria-label="Permalink to “🧠 Key Takeaways”">​</a></h2><ul><li>DFS = good for <em>existence</em> of a path.</li><li>BFS = good for <em>shortest</em> path.</li><li>Use recursion or stacks/queues to manage state.</li><li>Maze solving provides a practical foundation for:</li><li>Search algorithms</li><li>Graph traversal</li><li>Pathfinding logic (used later in tree and graph topics)</li></ul><h2 id="lab-project-and-exam" tabindex="-1">Lab, Project, and Exam <a class="header-anchor" href="#lab-project-and-exam" aria-label="Permalink to “Lab, Project, and Exam”">​</a></h2><p>Take a look at Lab 13 and Project 2.</p><p><a href="/csci-315/guides/midterm-study-guide">Study for the Midterm Exam.</a></p>`,31)])])}const m=t(l,[["render",n]]);export{g as __pageData,m as default};
